import '../../typing_test/model/typing_language.dart';
import 'practice_mode.dart';

/// Navigation payload for starting a practice attempt — the content was
/// already generated by PracticeContentGenerator on the dashboard, so the
/// practice screen itself never talks to the database or generates
/// content; it only ever drives TypingEngine with what it's given.
class MistakePracticeArgs {
  const MistakePracticeArgs({
    required this.language,
    required this.mode,
    required this.content,
    required this.practicedCharacters,
  });

  final TypingLanguage language;
  final PracticeMode mode;
  final String content;

  /// The weak characters this drill was built around (empty for Word /
  /// Skipped Word / General practice) — used only to report "weak
  /// characters practiced" on the result screen.
  final List<String> practicedCharacters;
}
